import numpy as np,json
from scipy.spatial.transform import Rotation as R
spec=json.load(open('/app/output/spec.json'))
def point(cam,u,v,folder='initial'):
 d=np.load(f'/app/output/{folder}/depth_{cam}.npy')[-1]; z=float(d[v,u]); K=np.array(spec['cameras'][cam]['intrinsic_cv']); T=np.array(spec['cameras'][cam]['cam2world_gl']); return (T@np.array([(u-160)*z/K[0,0],-(v-160)*z/K[1,1],-z,1]))[:3]
def tf(p,rot):
 T=np.eye(4);T[:3,3]=p;T[:3,:3]=rot;return T
origins=[([0,0,.333],0),([0,0,0],-90),([0,-.316,0],90),([.0825,0,0],90),([-.0825,.384,0],-90),([0,0,0],90),([.088,0,0],90)]
def fk(q):
 T=tf([0,-.4,.78],R.from_euler('z',90,degrees=True).as_matrix())
 for a,(p,rx) in zip(q,origins):T=T@tf(p,R.from_euler('x',rx,degrees=True).as_matrix())@tf([0,0,0],R.from_euler('z',a).as_matrix())
 return T@tf([0,0,.107],R.from_euler('z',-45,degrees=True).as_matrix())
if __name__=='__main__':
 m=json.load(open('/app/output/initial/meta.json'))['proprio']['now'];T=fk(m[:7]);print('FK',T,'obs',m[16:23]);
 for cam,uv in [('right',(201,145)),('right',(239,246)),('right',(210,236)),('left',(120,156)),('right',(159,144)),('right',(223,164))]:print(cam,uv,point(cam,*uv))
PY
